/* 학습 해설
 * OF cell cursor·누적숫자와pointer증가
 * 부팅의DTB자료를메모리·cmdline·initrd·reserved영역과연결하고연속blob을device_node/property연결구조로확장하는원리와수명을읽습니다.
 * 현재cellpointer를저장하고callerpointer를s만큼옮긴뒤of_read_number(p,s)를반환합니다. pointer-to-pointer로주소/길이쌍의순차파싱상태를갱신합니다. 입력폭·배열끝·값표현범위는caller와of_read_number계약에의존합니다.
 * 실제[1,2,3]에서s2는0x100000002/cursor+2,다음s1은3/+3검산을읽습니다. pointer변경과값decode의두효과를다르게표시합니다.
 */
u64 __init dt_mem_next_cell(int s, const __be32 **cellp)
{
	const __be32 *p = *cellp;

	*cellp = p + s;
	return of_read_number(p, s);
}

/*
 * early_init_dt_scan_memory - Look for and parse memory nodes
 */
int __init early_init_dt_scan_memory(void)
{
	int node, found_memory = 0;
	const void *fdt = initial_boot_params;

	fdt_for_each_subnode(node, fdt, 0) {
		const char *type = of_get_flat_dt_prop(node, "device_type", NULL);
		const __be32 *reg, *endp;
		int l;
		bool hotpluggable;

		/* We are scanning "memory" nodes only */
		if (type == NULL || strcmp(type, "memory") != 0)
			continue;

