annotated:
/* 학습 해설
 * OF memory node 선택·직계child와status
 * 부팅의DTB자료를메모리·cmdline·initrd·reserved영역과연결하고연속blob을device_node/property연결구조로확장하는원리와수명을읽습니다.
 * root직계child중device_type이memory인사용가능node만선택합니다. linux,usable-memory를먼저읽고없으면reg를쓰며둘다없으면넘깁니다. hotpluggable은property존재로표현됩니다. 이름만memory인모든node를무조건등록하는구현이아닙니다.
 * device_type/status/reg우선순위를조건표로적습니다. 앞statushelper와flatproperty조회의호출관계를연결하고이실행fixture가전체memoryscan을실행하지않았다고표시합니다.
 */
int __init early_init_dt_scan_memory(void)
{
	int node, found_memory = 0;
	const void *fdt = initial_boot_params;

	fdt_for_each_subnode(node, fdt, 0) {
		const char *type = of_get_flat_dt_prop(node, "device_type", NULL);
		const __be32 *reg, *endp;
		int l;
		bool hotpluggable;

		/* We are scanning "memory" nodes only */
		if (type == NULL || strcmp(type, "memory") != 0)
			continue;

		if (!of_fdt_device_is_available(fdt, node))
			continue;

		reg = of_get_flat_dt_prop(node, "linux,usable-memory", &l);
		if (reg == NULL)
			reg = of_get_flat_dt_prop(node, "reg", &l);
		if (reg == NULL)
			continue;

		endp = reg + (l / sizeof(__be32));
		hotpluggable = of_get_flat_dt_prop(node, "hotpluggable", NULL);

