/* 학습 해설
 * OF chosen 처리·없는node도cmdline설정 적용
 * 부팅의DTB자료를메모리·cmdline·initrd·reserved영역과연결하고연속blob을device_node/property연결구조로확장하는원리와수명을읽습니다.
 * chosen부재면chosen@0을찾고그마저없으면handle_cmdline으로갑니다. node가있으면offset을저장하고initrd/elfcorehdr를읽습니다. 없는chosen이곧함수오류반환이아니며설정commandlinefallback은계속처리하고반환0입니다.
 * node없음/있음의경로를그립니다. chosen_node_offset이초기NOTFOUNDunsigned표현이라는점과usable-range의signed검사를연결하고C의goto분기원리를표시합니다.
 */
int __init early_init_dt_scan_chosen(char *cmdline)
{
	int l, node;
	const char *p;
	const void *rng_seed;
	const void *fdt = initial_boot_params;

	node = fdt_path_offset(fdt, "/chosen");
	if (node < 0)
		node = fdt_path_offset(fdt, "/chosen@0");
	if (node < 0)
		/* Handle the cmdline config options even if no /chosen node */
		goto handle_cmdline;

	chosen_node_offset = node;

	early_init_dt_check_for_initrd(node);
	early_init_dt_check_for_elfcorehdr(node);

	rng_seed = of_get_flat_dt_prop(node, "rng-seed", &l);
	if (rng_seed && l > 0) {
		add_bootloader_randomness(rng_seed, l);

		/* try to clear seed so it won't be found. */
		fdt_nop_property(initial_boot_params, node, "rng-seed");

