/* 학습 해설
 * OF 물리메모리 page정렬·앞부분잘라내기
 * 부팅의DTB자료를메모리·cmdline·initrd·reserved영역과연결하고연속blob을device_node/property연결구조로확장하는원리와수명을읽습니다.
 * 범위가다음page경계까지길이보다작으면버립니다. base가unaligned이면그앞bytes를size에서빼고base를올린뒤size를PAGE_MASK로내립니다. 작은정상범위에서page단위등록할완전영역을골라내는기술이며모든u64overflowguard를이본문이제공하지않습니다.
 * page4096에서base0x2001/size0x2fff가base0x3000/size0x2000인실제검산을읽습니다. provider는memblock호출기록만수행하며실제물리메모리를등록하지않습니다.
 */
void __init __weak early_init_dt_add_memory_arch(u64 base, u64 size)
{
	const u64 phys_offset = MIN_MEMBLOCK_ADDR;

	if (size < PAGE_SIZE - (base & ~PAGE_MASK)) {
		pr_warn("Ignoring memory block 0x%llx - 0x%llx\n",
			base, base + size);
		return;
	}

	if (!PAGE_ALIGNED(base)) {
		size -= PAGE_SIZE - (base & ~PAGE_MASK);
		base = PAGE_ALIGN(base);
	}
	size &= PAGE_MASK;

	if (base > MAX_MEMBLOCK_ADDR) {
		pr_warn("Ignoring memory block 0x%llx - 0x%llx\n",
			base, base + size);
		return;
	}

	if (base + size - 1 > MAX_MEMBLOCK_ADDR) {
		pr_warn("Ignoring memory range 0x%llx - 0x%llx\n",
			((u64)MAX_MEMBLOCK_ADDR) + 1, base + size);
		size = MAX_MEMBLOCK_ADDR - base + 1;

