/* 학습 해설
 * OF boot scan 순서·chosen memory usable
 * 부팅의DTB자료를메모리·cmdline·initrd·reserved영역과연결하고연속blob을device_node/property연결구조로확장하는원리와수명을읽습니다.
 * chosen에서cmdline/initrd등을읽은뒤memory를scan하고usable-range를적용합니다. early_init_dt_scan은verify실패면false,성공이면이scan을호출하고true입니다. scan_nodes는전체하위단계의오류를bool로모아전파하는구조가아닙니다.
 * verify→chosen→memory→usable범위를시간순서로그립니다. usable제한전에memory등록이이루어지는이유와반환정책의실제범위를주석달아봅니다.
 */
void __init early_init_dt_scan_nodes(void)
{
	int rc;

	/* Retrieve various information from the /chosen node */
	rc = early_init_dt_scan_chosen(boot_command_line);
	if (rc)
		pr_warn("No chosen node found, continuing without\n");

	/* Setup memory, calling early_init_dt_add_memory_arch */
	early_init_dt_scan_memory();

	/* Handle linux,usable-memory-range property */
	early_init_dt_check_for_usable_mem_range();
}

