/* 학습 해설
 * OF boot unflatten·ACPI와빈rootfallback
 * 부팅의DTB자료를메모리·cmdline·initrd·reserved영역과연결하고연속blob을device_node/property연결구조로확장하는원리와수명을읽습니다.
 * ACPI가켜져있으면bootloaderDTB를사용하지않고NULL로선택합니다. blob이없으면built-inemptyroot를사용하되header총길이가linkerstart/end범위를넘으면끝냅니다. 정상emptyroot는CRC를계산하고copy한뒤expandedtree를만듭니다.
 * ACPI켜짐/DTB없음/정상bootDTB의선택표를만듭니다. __dtb_empty_root_begin/end가빌드시생기는기호임을읽고실제ACPI초기화실행을검증했다고설명하지않습니다.
 */
void __init unflatten_device_tree(void)
{
	void *fdt = initial_boot_params;

	/* Don't use the bootloader provided DTB if ACPI is enabled */
	if (!acpi_disabled)
		fdt = NULL;

	/*
	 * Populate an empty root node when ACPI is enabled or bootloader
	 * doesn't provide one.
	 */
	if (!fdt) {
		fdt = (void *) __dtb_empty_root_begin;
		/* fdt_totalsize() will be used for copy size */
		if (fdt_totalsize(fdt) >
		    __dtb_empty_root_end - __dtb_empty_root_begin) {
			pr_err("invalid size in dtb_empty_root\n");
			return;
		}
		of_fdt_crc32 = crc32_be(~0, fdt, fdt_totalsize(fdt));
		fdt = copy_device_tree(fdt);
	}

	__unflatten_device_tree(fdt, NULL, &of_root,
				early_init_dt_alloc_memory_arch, false);

