 * DTB예약메모리를고정배열과부팅allocator에연결하고정렬·범위선택·callback·장치연결목록·잠금·해제의원리와오류정책을원문에서읽습니다.
 * base를 output에 먼저 저장하고 no-map이면 mark_nomap합니다. mark실패면 해당물리공간을free하지만 outputbase를0으로 되돌리지 않습니다. kmemleak_ignore_phys는 그뒤 호출되고 mark오류를 반환합니다. 실제provider에서 EBUSY/free1과 nonzerooutput잔존을 확인했습니다.
 * 할당→output→mark→실패free→ignore→오류return의순서를 그립니다. 호출자는오류를먼저 확인해야 하며 nonzero주소만으로성공이라고판정하면안되는 이유를 뒤 alloc_size와연결합니다.
 */
static int __init early_init_dt_alloc_reserved_memory_arch(phys_addr_t size,
	phys_addr_t align, phys_addr_t start, phys_addr_t end, bool nomap,
	phys_addr_t *res_base)
{
	phys_addr_t base;
	int err = 0;

	end = !end ? MEMBLOCK_ALLOC_ANYWHERE : end;
	align = !align ? SMP_CACHE_BYTES : align;
	base = memblock_phys_alloc_range(size, align, start, end);
	if (!base)
		return -ENOMEM;

	*res_base = base;
	if (nomap) {
		err = memblock_mark_nomap(base, size);
		if (err)
			memblock_phys_free(base, size);
	}

	kmemleak_ignore_phys(base);

	return err;
}

