 * OF reserved no-map예약·메모리겹침과기예약
 * DTB예약메모리를고정배열과부팅allocator에연결하고정렬·범위선택·callback·장치연결목록·잠금·해제의원리와오류정책을원문에서읽습니다.
 * no-map에서 memory와겹치고이미예약된경우 EBUSY입니다. 메모리와겹치지않으면 기예약조건만으로같은거부를하지않습니다. 나머지노-map은mark_nomap, 일반은memblock_reserve로위임합니다. no-map 표시와 일반예약을 같은API라고설명하지않습니다.
 * memoryoverlap/기예약 두bool의조합을표로적습니다. 실제provider에서두조건true거부와overlapfalse허용을읽고실제memblockinterval검색은다른원문을읽어야합니다.
 */
static int __init early_init_dt_reserve_memory(phys_addr_t base,
					       phys_addr_t size, bool nomap)
{
	if (nomap) {
		/*
		 * If the memory is already reserved (by another region), we
		 * should not allow it to be marked nomap, but don't worry
		 * if the region isn't memory as it won't be mapped.
		 */
		if (memblock_overlaps_region(&memblock.memory, base, size) &&
		    memblock_is_region_reserved(base, size))
			return -EBUSY;

		return memblock_mark_nomap(base, size);
	}
	return memblock_reserve(base, size);
}

