/* 학습 해설
 * OF reserved root형식·cell일치와ranges존재
 * DTB예약메모리를고정배열과부팅allocator에연결하고정렬·범위선택·callback·장치연결목록·잠금·해제의원리와오류정책을원문에서읽습니다.
 * reserved-memory의size/addresscellproperty가있고root값과같아야합니다. rangesproperty도존재해야하며본문은내용길이를받아empty인지확인하지않습니다. 정상BE32자료계약과지원root형식을검사하는단계이며전체장치트리의모든형식을검증하지않습니다.
 * cell불일치/부재/ranges부재의EINVAL을표로적습니다. ranges존재검사와emptytranslation규칙의문서계약을구별하고원문의guard를없는추가검사로설명하지않습니다.
 */
static int __init __reserved_mem_check_root(unsigned long node)
{
	const __be32 *prop;

	prop = of_get_flat_dt_prop(node, "#size-cells", NULL);
	if (!prop || be32_to_cpup(prop) != dt_root_size_cells)
		return -EINVAL;

	prop = of_get_flat_dt_prop(node, "#address-cells", NULL);
	if (!prop || be32_to_cpup(prop) != dt_root_addr_cells)
		return -EINVAL;

	prop = of_get_flat_dt_prop(node, "ranges", NULL);
	if (!prop)
		return -EINVAL;
	return 0;
}

