/* 학습 해설
 * OF reserved 정렬비교·base size node의사전순
 * DTB예약메모리를고정배열과부팅allocator에연결하고정렬·범위선택·callback·장치연결목록·잠금·해제의원리와오류정책을원문에서읽습니다.
 * base가작은것을먼저두고같으면size,다시같으면fdt_node를비교해-1/0/1을반환합니다. base0/size0동적entry를base0의staticentry앞에두려는순서입니다. 차이를뺄셈후int변환하지않고직접비교해선택정수순서를표현합니다.
 * 27가지작은key조합의쌍729와삼중19683transitivity검산을읽습니다. 직접비교로동점순서를만드는원리와원본sort알고리즘은별도파일이라는범위를표시합니다.
 */
static int __init __rmem_cmp(const void *a, const void *b)
{
	const struct reserved_mem *ra = a, *rb = b;

	if (ra->base < rb->base)
		return -1;

	if (ra->base > rb->base)
		return 1;

	/*
	 * Put the dynamic allocations (address == 0, size == 0) before static
	 * allocations at address 0x0 so that overlap detection works
	 * correctly.
	 */
	if (ra->size < rb->size)
		return -1;
	if (ra->size > rb->size)
		return 1;

	if (ra->fdt_node < rb->fdt_node)
		return -1;
	if (ra->fdt_node > rb->fdt_node)
		return 1;

	return 0;

